نقش سازمانی: retail_logistics_manager (retail_logistics_manager)

درخواست کاربر:
ریشه‌یابی تأخیرهای توزیع این هفته. (شمال)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "dock_log",
      "description": "صف بارگیری مرکز توزیع",
      "dimensions": [
        "day"
      ],
      "measures": [
        "avg_queue_hours",
        "docked_trucks"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "on_time_delivery",
      "description": "تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "route"
      ]
    },
    {
      "metric": "dock_dwell",
      "description": "توقف وانت در بارگیری",
      "formula": "میانگین ساعت صف تا تخلیه",
      "unit": "ساعت",
      "dimensions": [
        "day"
      ]
    }
  ],
  "business_context": [
    "پنجرهٔ تحویل توافقی با شعبه‌ها دو ساعت",
    "اسلات‌بندی بارگیری از ساعت ۵ صبح آغاز می‌شود",
    "مرکز توزیع واحد و ۲۶ مسیر توزیع برای ۱۲۰ شعبه"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "on_time_delivery"
    ],
    "period_a": "prev_week",
    "period_b": "curr_week"
  }
}

TOOL_OBSERVATION:
{
  "route": "مسیر شمال الف",
  "on_time_pct": {
    "prev": 90.6,
    "curr": 79.1,
    "change_pp": -11.5
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "dock_log",
    "filters": {
      "period": [
        "prev_week",
        "curr_week"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "avg_queue_hours": {
    "prev": 1.2,
    "curr": 3.1,
    "change_h": 1.9
  },
  "trucks_before_slot": "53٪ وانت‌ها بدون اسلات آمده‌اند"
}

