چرا هر تحویل گران‌تر شده؟ زنجیره را باز کن. (مرکز)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "fleet_utilization",
      "description": "اشغال و مصرف ناوگان",
      "dimensions": [
        "vehicle_class",
        "week"
      ],
      "measures": [
        "load_pct",
        "fuel_liters",
        "trips"
      ]
    },
    {
      "dataset": "dock_log",
      "description": "صف بارگیری مرکز توزیع",
      "dimensions": [
        "day"
      ],
      "measures": [
        "avg_queue_hours",
        "docked_trucks"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_delivery",
      "description": "هزینهٔ هر تحویل",
      "formula": "هزینهٔ مسیر تقسیم بر تعداد تحویل",
      "unit": "میلیون تومان",
      "dimensions": [
        "route"
      ]
    },
    {
      "metric": "dock_dwell",
      "description": "توقف وانت در بارگیری",
      "formula": "میانگین ساعت صف تا تخلیه",
      "unit": "ساعت",
      "dimensions": [
        "day"
      ]
    }
  ],
  "business_context": [
    "اسلات‌بندی بارگیری از ساعت ۵ صبح آغاز می‌شود",
    "ناوگان اختصاصی و باربری بیرونی به‌صورت ترکیبی",
    "پنجرهٔ تحویل توافقی با شعبه‌ها دو ساعت"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "cost_per_delivery"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "route_group": "مرکز",
  "cost_per_delivery_m": {
    "prev": 18.6,
    "curr": 24.2,
    "change_pct": 30.1
  },
  "deliveries": {
    "prev": 144,
    "curr": 125
  }
}

TOOL_CALL:
