درخواست کاربر:
ناوگان اختصاصی نگه داریم یا بیشتر برون‌سپاری کنیم؟ عدد بده. (مدیر توزیع — زنجیرهٔ شهروند)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "fleet_utilization",
      "description": "اشغال و مصرف ناوگان",
      "dimensions": [
        "vehicle_class",
        "week"
      ],
      "measures": [
        "load_pct",
        "fuel_liters",
        "trips"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_delivery",
      "description": "هزینهٔ هر تحویل",
      "formula": "هزینهٔ مسیر تقسیم بر تعداد تحویل",
      "unit": "میلیون تومان",
      "dimensions": [
        "route"
      ]
    },
    {
      "metric": "fleet_utilization",
      "description": "اشغال ناوگان",
      "formula": "بار مفید تقسیم بر ظرفیت",
      "unit": "درصد",
      "dimensions": [
        "vehicle_class"
      ]
    }
  ],
  "business_context": [
    "پنجرهٔ تحویل توافقی با شعبه‌ها دو ساعت",
    "اسلات‌بندی بارگیری از ساعت ۵ صبح آغاز می‌شود",
    "مرکز توزیع واحد و ۲۶ مسیر توزیع برای ۱۲۰ شعبه"
  ]
}

