«مسیر شمال الف» دیر می‌رسد؛ ریشه را پیدا کن. (مدیر توزیع — فروشگاه‌های زنجیره‌ای رفاه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "dock_log",
      "description": "صف بارگیری مرکز توزیع",
      "dimensions": [
        "day"
      ],
      "measures": [
        "avg_queue_hours",
        "docked_trucks"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "on_time_delivery",
      "description": "تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "route"
      ]
    },
    {
      "metric": "dock_dwell",
      "description": "توقف وانت در بارگیری",
      "formula": "میانگین ساعت صف تا تخلیه",
      "unit": "ساعت",
      "dimensions": [
        "day"
      ]
    }
  ],
  "business_context": [
    "مرکز توزیع واحد و ۲۶ مسیر توزیع برای ۱۲۰ شعبه",
    "زنجیرهٔ سرد برای لبنیات و سرمودی الزامی است",
    "ناوگان اختصاصی و باربری بیرونی به‌صورت ترکیبی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "on_time_delivery"
    ],
    "period_a": "prev_week",
    "period_b": "curr_week"
  }
}

TOOL_OBSERVATION:
{
  "route": "مسیر شمال الف",
  "on_time_pct": {
    "prev": 90.4,
    "curr": 75.1,
    "change_pp": -15.3
  }
}

TOOL_CALL:
